/**
 * The result of a single-tree MST computation: the chosen edges and their total
 * weight. For a single-vertex component this holds no edges and zero weight.
 */
record MstResult(List<Edge> edges, long totalWeight) {
    MstResult {
        edges = List.copyOf(edges);
    }
}

/**
 * The result of a Minimum Spanning Forest computation: one {@link MstResult} per
 * connected component, in ascending order of each component's lowest vertex index.
 */
record MsfResult(List<MstResult> components) {
    MsfResult {
        components = List.copyOf(components);
    }

    /** The number of connected components (trees) in the forest. */
    int componentCount() {
        return components.size();
    }

    /** Every edge across all component trees. */
    List<Edge> edges() {
        return components.stream().flatMap(component -> component.edges().stream()).toList();
    }

    /** The combined weight of all component trees. */
    long totalWeight() {
        return components.stream().mapToLong(MstResult::totalWeight).sum();
    }
}

